eval $'nvm_version () \n{ \n    local PATTERN;\n    PATTERN="${1-}";\n    local VERSION;\n    if [ -z "${PATTERN}" ]; then\n        PATTERN=\'current\';\n    fi;\n    if [ "${PATTERN}" = "current" ]; then\n        nvm_ls_current;\n        return $?;\n    fi;\n    local NVM_NODE_PREFIX;\n    NVM_NODE_PREFIX="$(nvm_node_prefix)";\n    case "_${PATTERN}" in \n        "_${NVM_NODE_PREFIX}" | "_${NVM_NODE_PREFIX}-")\n            PATTERN="stable"\n        ;;\n    esac;\n    VERSION="$(nvm_ls "${PATTERN}" | command tail -1)";\n    if [ -z "${VERSION}" ] || [ "_${VERSION}" = "_N/A" ]; then\n        nvm_echo "N/A";\n        return 3;\n    fi;\n    nvm_echo "${VERSION}"\n}' > /dev/null 2>&1
eval $'nvm_version_dir () \n{ \n    local NVM_WHICH_DIR;\n    NVM_WHICH_DIR="${1-}";\n    if [ -z "${NVM_WHICH_DIR}" ] || [ "${NVM_WHICH_DIR}" = "new" ]; then\n        nvm_echo "${NVM_DIR}/versions/node";\n    else\n        if [ "_${NVM_WHICH_DIR}" = "_iojs" ]; then\n            nvm_echo "${NVM_DIR}/versions/io.js";\n        else\n            if [ "_${NVM_WHICH_DIR}" = "_old" ]; then\n                nvm_echo "${NVM_DIR}";\n            else\n                nvm_err \'unknown version dir\';\n                return 3;\n            fi;\n        fi;\n    fi\n}' > /dev/null 2>&1
eval $'nvm_version_greater () \n{ \n    command awk \'BEGIN {\n    if (ARGV[1] == "" || ARGV[2] == "") exit(1)\n    split(ARGV[1], a, /\\./);\n    split(ARGV[2], b, /\\./);\n    for (i=1; i<=3; i++) {\n      if (a[i] && a[i] !~ /^[0-9]+$/) exit(2);\n      if (b[i] && b[i] !~ /^[0-9]+$/) { exit(0); }\n      if (a[i] < b[i]) exit(3);\n      else if (a[i] > b[i]) exit(0);\n    }\n    exit(4)\n  }\' "${1#v}" "${2#v}"\n}' > /dev/null 2>&1
eval $'nvm_version_greater_than_or_equal_to () \n{ \n    command awk \'BEGIN {\n    if (ARGV[1] == "" || ARGV[2] == "") exit(1)\n    split(ARGV[1], a, /\\./);\n    split(ARGV[2], b, /\\./);\n    for (i=1; i<=3; i++) {\n      if (a[i] && a[i] !~ /^[0-9]+$/) exit(2);\n      if (a[i] < b[i]) exit(3);\n      else if (a[i] > b[i]) exit(0);\n    }\n    exit(0)\n  }\' "${1#v}" "${2#v}"\n}' > /dev/null 2>&1
eval $'nvm_version_path () \n{ \n    local VERSION;\n    VERSION="${1-}";\n    if [ -z "${VERSION}" ]; then\n        nvm_err \'version is required\';\n        return 3;\n    else\n        if nvm_is_iojs_version "${VERSION}"; then\n            nvm_echo "$(nvm_version_dir iojs)/$(nvm_strip_iojs_prefix "${VERSION}")";\n        else\n            if nvm_version_greater 0.12.0 "${VERSION}"; then\n                nvm_echo "$(nvm_version_dir old)/${VERSION}";\n            else\n                nvm_echo "$(nvm_version_dir new)/${VERSION}";\n            fi;\n        fi;\n    fi\n}' > /dev/null 2>&1
